const REDACTED = "[REDACTED]";
const SENSITIVE_FIELD_PATTERN = /^(authorization|cookie|api[_-]?key|password|secret|token|access[_-]?token|refresh[_-]?token|bearer)$/i;
const OPENAI_LIKE_SECRET_PATTERN = /(^|[^A-Za-z0-9_-])(sk-(?:proj-|svcacct-)?[A-Za-z0-9_-]{24,})(?=$|[^A-Za-z0-9_-])/g;
export function redactSensitiveFields(value) {
    return redactWalk(value, new WeakSet());
}
function redactWalk(value, seen) {
    if (value === null || typeof value !== "object")
        return value;
    if (seen.has(value))
        return "[Circular]";
    seen.add(value);
    if (Array.isArray(value))
        return value.map((v) => redactWalk(v, seen));
    const out = {};
    for (const [key, entry] of Object.entries(value)) {
        out[key] = SENSITIVE_FIELD_PATTERN.test(key)
            ? REDACTED
            : redactWalk(entry, seen);
    }
    return out;
}
export function sanitizeToolErrorText(value) {
    let out = value;
    out = out.replace(/\bBearer\s+[^,\s;)}\]]+/gi, `Bearer ${REDACTED}`);
    out = out.replace(OPENAI_LIKE_SECRET_PATTERN, `$1${REDACTED}`);
    out = out.replace(/([?&](?:authorization|cookie|api[_-]?key|password|secret|token|access[_-]?token|refresh[_-]?token|bearer)=)[^&#\s]+/gi, `$1${REDACTED}`);
    out = out.replace(/((?:^|[^A-Za-z0-9_-])(?:"|')?(?:authorization|cookie|api[_-]?key|password|secret|token|access[_-]?token|refresh[_-]?token|bearer)(?:"|')?\s*[:=]\s*)(?:"[^"]*"|'[^']*'|[^,\s;)}\]]+)/gi, (_match, prefix) => `${prefix}${REDACTED}`);
    return out;
}
export function sanitizeToolErrorValue(value) {
    if (value instanceof Error)
        return sanitizeToolErrorText(value.message);
    if (typeof value === "string")
        return sanitizeToolErrorText(value);
    try {
        return sanitizeToolErrorText(JSON.stringify(redactSensitiveFields(value), null, 2));
    }
    catch {
        return sanitizeToolErrorText(String(value));
    }
}
